def transform(grid):
    out=[row[:] for row in grid]
    # The two repeated 6 objects have matching shapes; the 8 marker indicates
    # recoloring the first (upper) matching object to color 8.
    h,w=len(grid),len(grid[0])
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]==6 and (r,c) not in seen:
          q=[(r,c)];seen.add((r,c));co=[]
          while q:
            y,x=q.pop();co.append((y,x))
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
              a,b=y+dy,x+dx
              if 0<=a<h and 0<=b<w and grid[a][b]==6 and (a,b) not in seen: seen.add((a,b));q.append((a,b))
          comps.append(co)
    def shape(co):
      a=min(r for r,c in co);b=min(c for r,c in co)
      return frozenset((r-a,c-b) for r,c in co)
    for i,a in enumerate(comps):
      for b in comps[i+1:]:
        if shape(a)==shape(b):
          target=min((a,b),key=lambda co:min(r for r,c in co))
          for r,c in target: out[r][c]=8
          return out
    return out
