def transform(grid):
    out=[row[:] for row in grid]
    # When a pair of congruent objects is present, recolor the lower one
    # using the color of the distinct marker object.
    h,w=len(grid),len(grid[0])
    seen=set(); objs=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c] and (r,c) not in seen:
          col=grid[r][c];q=[(r,c)];seen.add((r,c));co=[]
          while q:
            y,x=q.pop();co.append((y,x))
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
              a,b=y+dy,x+dx
              if 0<=a<h and 0<=b<w and grid[a][b]==col and (a,b) not in seen:
                seen.add((a,b));q.append((a,b))
          objs.append((col,co))
    def sh(co):
      a=min(y for y,x in co);b=min(x for y,x in co)
      return frozenset((y-a,x-b) for y,x in co)
    groups={}
    for col,co in objs: groups.setdefault(sh(co),[]).append((col,co))
    for vals in groups.values():
      if len(vals)>=2:
        # lower matching instance takes color of the small isolated marker
        vals=sorted(vals,key=lambda z:min(y for y,x in z[1]))
        marker=next((col for col,co in objs if col not in (0,vals[0][0]) and len(co)<=2),8)
        co=vals[-1][1]
        for y,x in co: out[y][x]=marker
        break
    return out
