def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Recolor the lower of the two identical 6 polyominoes with the isolated
    # marker color (8), preserving the upper matching example.
    seen=set(); objects=[]
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v==0 or (r,c) in seen: continue
            q=[(r,c)];seen.add((r,c));co=[]
            while q:
                y,x=q.pop();co.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=y+dy,x+dx
                    if 0<=a<h and 0<=b<w and grid[a][b]==v and (a,b) not in seen:
                        seen.add((a,b));q.append((a,b))
            objects.append((v,co))
    def shape(co):
        a=min(r for r,c in co);b=min(c for r,c in co)
        return frozenset((r-a,c-b) for r,c in co)
    six=[co for v,co in objects if v==6]
    if len(six)>=2:
        for i,a in enumerate(six):
            for b in six[i+1:]:
                if shape(a)==shape(b):
                    lower=max((a,b),key=lambda co:min(r for r,c in co))
                    for r,c in lower: out[r][c]=8
                    return out
    return out
